/* ACCAD Trace — reçu 80 mm : image identique à l'écran, au PDF et à l'impression thermique */
(function (root) {
  'use strict';
  const A = root.ACCAD;
  const LOGO_DATA_URL = 'data:image/png;base64,';
  const W = 576; // 80 mm à 203 dpi (largeur utile des imprimantes thermiques)

  A.receipt = {
    fromServer(operation, payment) {
      const ref = (payment && payment.REFERENCE_RECU) || operation.REFERENCE_OPERATION;
      return { id: operation.ID_OPERATION, reference: ref, montant: operation.MONTANT, devise: operation.DEVISE, plaque: operation.NUMERO_PLAQUE, typeCamion: operation.TYPE_CAMION_SNAPSHOT, agence: operation.NOM_AGENCE, exportateur: operation.NOM_EXPORTATEUR, produit: operation.PRODUIT, agentName: operation.NOM_AGENT_SNAPSHOT, agentId: operation.ID_AGENT_PERCEPTION, agentPhone: operation.TELEPHONE_AGENT_SNAPSHOT, date: (payment && payment.DATE_PAIEMENT) || operation.DATE_PAIEMENT, time: (payment && payment.HEURE_PAIEMENT) || operation.HEURE_PAIEMENT, qr: A.qrPayload(ref, operation.NUMERO_PLAQUE, operation.ID_AGENT_PERCEPTION, (payment && payment.DATE_PAIEMENT) || operation.DATE_PAIEMENT), site: operation.SITE_OPERATION || '' };
    },
    fromCache(r) { return { id: r.idOperation, reference: r.reference, montant: r.montant, devise: r.devise, plaque: r.plaque, typeCamion: r.typeCamion, agence: r.agence, exportateur: r.exportateur, produit: r.produit, agentName: r.agentName, agentId: r.agentId, agentPhone: r.agentPhone, date: r.date, time: r.time, qr: A.qrPayload(r.reference, r.plaque, r.agentId, r.date), site: r.site }; },
    fileName(r) { const [d, m, y] = String(r.date).split('-'); const t = String(r.time).replace(/:/g, ''); return `ACCAD_TRACE_${y}${m}${d}_${t}_${String(r.reference).replace(/[^A-Za-z0-9-]/g, '')}.pdf`; },

    /** Dessine le reçu. Retourne la hauteur utilisée. `ctx` peut être un contexte réel ou un contexte de mesure. */
    draw(ctx, r, logo, matrix) {
      const FONT = 'Arial, Helvetica, sans-serif', PADX = 28; let y = 26;
      const text = (str, size, weight, align, color) => { ctx.font = `${weight || 'normal'} ${size}px ${FONT}`; ctx.fillStyle = color || '#000'; ctx.textAlign = align || 'left'; ctx.textBaseline = 'top'; ctx.fillText(str, align === 'center' ? W / 2 : align === 'right' ? W - PADX : PADX, y); };
      const wrap = (str, size, weight, maxW) => { ctx.font = `${weight} ${size}px ${FONT}`; const words = String(str).split(' '); const lines = []; let line = ''; words.forEach((w) => { while (ctx.measureText(w).width > maxW) { let cut = w.length - 1; while (cut > 1 && ctx.measureText(w.slice(0, cut)).width > maxW) cut--; if (line) { lines.push(line); line = ''; } lines.push(w.slice(0, cut)); w = w.slice(cut); } const t = line ? line + ' ' + w : w; if (ctx.measureText(t).width > maxW && line) { lines.push(line); line = w; } else line = t; }); if (line) lines.push(line); return lines; };
      const dashed = () => { ctx.fillStyle = '#000'; for (let x = PADX; x < W - PADX; x += 12) ctx.fillRect(x, y, 6, 2); y += 14; };
      const center = (str, size, weight, gap) => { text(str, size, weight, 'center'); y += size + (gap || 6); };
      center('RÉPUBLIQUE DÉMOCRATIQUE DU CONGO', 23, 'bold');
      center('Gouvernement provincial du Nord-Kivu', 22, 'normal');
      center('Projet de développement', 22, 'normal');
      center('Province-FEC-ACCAD', 24, 'bold', 12);
      if (logo) { const h = 118, w = Math.round(h * (logo.width / logo.height)); ctx.drawImage(logo, Math.round((W - w) / 2), y, w, h); y += h + 12; }
      dashed();
      center('REÇU DE PERCEPTION', 30, 'bold', 8);
      wrap('N° ' + r.reference, 21, 'bold', W - 2 * PADX).forEach((l) => { text(l, 21, 'bold', 'center'); y += 27; });
      y += 4; dashed();
      const row = (label, value, big) => { text(label.toUpperCase(), 17, 'normal', 'left', '#444'); y += 22; const size = big ? 40 : 25; wrap(value || '—', size, 'bold', W - 2 * PADX).forEach((l) => { text(l, size, 'bold'); y += size + 5; }); y += 6; };
      row('Montant perçu', A.money(r.montant, r.devise), true);
      row('Plaque du camion', r.plaque);
      row('Type de camion', r.typeCamion);
      row('Agence en douane', r.agence);
      row('Exportateur', r.exportateur);
      row('Produit', r.produit);
      row('Agent de perception', r.agentName + (r.agentPhone ? '  ' + r.agentPhone : ''));
      row('Date et heure', `${String(r.date).replace(/-/g, '/')}  ${String(r.time).slice(0, 5)}`);
      dashed();
      if (matrix) { const n = matrix.size, mod = Math.max(4, Math.floor(300 / (n + 8))), side = mod * (n + 8), x0 = Math.round((W - side) / 2); ctx.fillStyle = '#fff'; ctx.fillRect(x0, y, side, side); ctx.fillStyle = '#000'; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (matrix.get(i, j)) ctx.fillRect(x0 + (j + 4) * mod, y + (i + 4) * mod, mod, mod); y += side + 10; }
      center('Contrôle : scanner ce code au poste de Kasindi', 17, 'normal', 4);
      center('Conservez ce reçu avec le camion.', 17, 'normal', 26);
      return y;
    },

    /** Génère le reçu sous forme de canvas. Dépendances injectables pour les tests. */
    async render(r, deps) {
      deps = deps || {};
      const makeCanvas = deps.createCanvas || ((w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; });
      const QR = deps.QRCode || root.QRCode;
      const matrix = QR.create(r.qr, { errorCorrectionLevel: 'M' }).modules;
      const logo = deps.logo !== undefined ? deps.logo : await loadLogo();
      const probe = makeCanvas(W, 4000); const height = Math.ceil(A.receipt.draw(probe.getContext('2d'), r, logo, matrix));
      const canvas = makeCanvas(W, height); const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, height); A.receipt.draw(ctx, r, logo, matrix);
      return canvas;
    },
    async show(r, container) {
      const canvas = await A.receipt.render(r);
      canvas.className = 'receipt-canvas'; canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', `Reçu ${r.reference}. Montant ${A.money(r.montant, r.devise)}. Plaque ${r.plaque}. ${r.date} ${r.time}.`);
      container.innerHTML = ''; container.appendChild(canvas); return canvas;
    },
    async pdfBytes(r, deps) { const canvas = await A.receipt.render(r, deps); const b64 = canvas.toDataURL('image/jpeg', 0.95).split(',')[1]; return A.pdf.fromJpeg(b64ToBytes(b64), canvas.width, canvas.height); },
    async downloadPdf(r) {
      const bytes = await A.receipt.pdfBytes(r); const blob = new Blob([bytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = A.receipt.fileName(r); document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    },
    async printThermal(r) {
      const canvas = await A.receipt.render(r); const src = canvas.toDataURL('image/png');
      const frame = document.createElement('iframe'); frame.setAttribute('aria-hidden', 'true'); frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0';
      document.body.appendChild(frame);
      const doc = frame.contentWindow.document;
      doc.open(); doc.write(`<!doctype html><html><head><meta charset="utf-8"><title>${A.esc(A.receipt.fileName(r))}</title><style>@page{size:80mm auto;margin:0}html,body{margin:0;padding:0;background:#fff}img{display:block;width:80mm;height:auto}</style></head><body><img alt="Reçu" src="${src}"></body></html>`); doc.close();
      const img = doc.querySelector('img');
      const go = () => { frame.contentWindow.focus(); frame.contentWindow.print(); setTimeout(() => frame.remove(), 60000); };
      if (img.complete) go(); else img.onload = go;
    }
  };

  function b64ToBytes(b64) { const bin = atob(b64); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
  let logoPromise;
  function loadLogo() { if (!logoPromise) logoPromise = new Promise((resolve) => { const img = new Image(); img.onload = () => resolve(img); img.onerror = () => resolve(null); img.src = LOGO_DATA_URL; }); return logoPromise; }
})(window);

/* ---- PDF minimal : une page 80 mm de large portant l'image du reçu (JPEG) ---- */
(function (root) {
  'use strict';
  const A = root.ACCAD;
  A.pdf = {
    fromJpeg(jpeg, wPx, hPx) {
      const wPt = 80 / 25.4 * 72, hPt = wPt * hPx / wPx;
      const enc = (s) => Uint8Array.from(Array.from(s, (c) => c.charCodeAt(0) & 255));
      const chunks = []; let offset = 0; const offsets = [];
      const push = (u8) => { chunks.push(u8); offset += u8.length; };
      const obj = (n, body) => { offsets[n] = offset; push(enc(`${n} 0 obj\n`)); if (typeof body === 'string') push(enc(body)); else body.forEach((p) => push(typeof p === 'string' ? enc(p) : p)); push(enc('\nendobj\n')); };
      const content = `q ${wPt.toFixed(3)} 0 0 ${hPt.toFixed(3)} 0 0 cm /Im0 Do Q`;
      push(enc('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n'));
      obj(1, '<< /Type /Catalog /Pages 2 0 R >>');
      obj(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
      obj(3, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${wPt.toFixed(3)} ${hPt.toFixed(3)}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);
      obj(4, [`<< /Type /XObject /Subtype /Image /Width ${wPx} /Height ${hPx} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`, jpeg, '\nendstream']);
      obj(5, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
      const xref = offset; let table = `xref\n0 6\n0000000000 65535 f \n`;
      for (let i = 1; i <= 5; i++) table += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
      push(enc(table + `trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`));
      const out = new Uint8Array(offset); let p = 0; chunks.forEach((c) => { out.set(c, p); p += c.length; }); return out;
    }
  };
})(window);
